def run_table(fn, cases):
    failed=[]
    for inp,exp in cases:
        try:
            got=fn(inp)
        except Exception as e:
            got=type(e).__name__
        if got!=exp: failed.append((inp,exp,got))
    return failed

def audit_grade():
    cases=[(100,"A"),(90,"A"),(89,"B"),(80,"B"),(79,"C"),(70,"C"),(69,"F"),(0,"F")]
    return run_table(grade,cases)

